def grids_from_text(text):
 rows=[]
 for line in text.splitlines():
  nums=re.findall(r'\b[0-9]\b',line)
  if len(nums)>=2: rows.append([int(x) for x in nums])
 # segmentation on each fully non-row labels? length consistency
 groups=[]; cur=[]
 for row in rows:
  if cur and len(cur[-1])!=len(row): groups.append(cur); cur=[]
  cur.append(row)
 if cur:groups.append(cur)
 return groups
