import numpy as np
from collections import deque,Counter

def comps(g,conn=8):
 a=np.array(g); H,W=a.shape; seen=set(); out=[]
 dirs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (conn==8 or abs(dr)+abs(dc)==1)]
 for r in range(H):
  for c in range(W):
   if a[r,c] and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); cells=[]
    while q:
     x,y=q.pop(); cells.append((x,y))
     for dr,dc in dirs:
      z=(x+dr,y+dc)
      if 0<=z[0]<H and 0<=z[1]<W and a[z]!=0 and z not in seen:
       seen.add(z);q.append(z)
    rs=[x for x,y in cells];cs=[y for x,y in cells]
    out.append((min(rs),min(cs),max(rs)+1,max(cs)+1, Counter(a[x,y] for x,y in cells),cells))
 return out
